<?= $this->extend('pos/layout') ?><?= $this->section('content') ?><div class="row toolbar"><p><?= count($rows) ?> recorded transactions</p><a class="button" href="<?= site_url('sales/new') ?>">+ Record sale</a></div><section class="panel table-wrap"><table><thead><tr><th>Sale / Date</th><th>Product</th><th>Customer</th><th>Staff</th><th>Quantity</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong>#<?= esc($r['id']) ?></strong><small><?= esc($r['created_at']) ?></small></td><td><?= esc($r['product']) ?></td><td><?= esc($r['customer']??'Walk-in customer') ?></td><td><?= esc($r['staff']) ?></td><td><?= esc($r['quantity']) ?></td><td><strong>₱<?= number_format((float)$r['total_price'],2) ?></strong></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">Your first sale starts here. Record a sale to see it in history.</td></tr><?php endif ?></tbody></table></section><p class="muted">Dates use Asia/Manila time. Totals are stored at the time of sale; names reflect the current directory.</p><?= $this->endSection() ?>
